namespace Ares.Structs.Game.Inventory;

/// <summary>The game's usable-item catalogue: every item an inventory slot can hold.</summary>
public static class UsableItems
{
    /// <summary>
    /// Number of names in the catalogue. A slot's asset index is the position of its item's technical name in the
    /// catalogue, ordered without case; names without a cooked item keep their index and have no entry.
    /// </summary>
    public const int Count = 898;

    /// <summary>Every cooked item, by usable index.</summary>
    public static IReadOnlyList<UsableItem> All { get; } =
    [
        .. UsableItemsPart0.Entries,
        .. UsableItemsPart1.Entries,
        .. UsableItemsPart2.Entries,
        .. UsableItemsPart3.Entries,
        .. UsableItemsPart4.Entries,
        .. UsableItemsPart5.Entries,
        .. UsableItemsPart6.Entries,
        .. UsableItemsPart7.Entries,
        .. UsableItemsPart8.Entries,
        .. UsableItemsPart9.Entries,
    ];

    /// <summary>Items by menu asset id, including every quality level's asset id.</summary>
    public static IReadOnlyDictionary<long, UsableItem> ByAssetId { get; } = All
        .SelectMany(item => item.QualityAssetIds.Count > 0 ? item.QualityAssetIds : [item.AssetId], (item, assetId) => (item, assetId))
        .ToDictionary(entry => entry.assetId, entry => entry.item);

    /// <summary>Items by technical name.</summary>
    public static IReadOnlyDictionary<string, UsableItem> ByTechnicalName { get; } =
        All.ToDictionary(item => item.TechnicalName, StringComparer.Ordinal);
}

